// Gabung Setelan dengan override dari item input run (mis. dari KRA).
const setelan = ($node['Setelan'] || [{}])[0] || {};
const masuk = ($node['Mulai'] || [{}])[0] || {};
const ambil = (kunci, fallback) => (masuk[kunci] !== undefined && masuk[kunci] !== '' ? masuk[kunci] : fallback);
const location = String(ambil('location', setelan.lokasi_proyek || '')).replace(/\/+$/, '');
const name = String(ambil('name', setelan.nama_proyek || 'KRA Cut'));
const media = String(ambil('media', setelan.file_media || ''));
const output = String(ambil('output', setelan.file_hasil || ''));
if (!location) throw new Error('Folder induk proyek kosong: isi env CONTOH_CONCAT_DIR di n100n atau kirim field "location" pada item input.');
if (!media) throw new Error('File media kosong: isi env CONTOH_CONCAT_MEDIA atau kirim field "media" pada item input.');
if (!output) throw new Error('File hasil export kosong: isi env CONTOH_CONCAT_OUTPUT atau kirim field "output" pada item input.');
const rencana = {
  bridge_url: setelan.bridge_url || 'http://127.0.0.1:5681',
  token: setelan.bridge_token || '',
  location,
  name,
  project_path: location + '/' + name,
  media,
  title: String(ambil('title', setelan.judul_video || name)),
  output,
  preset: String(ambil('preset', setelan.preset_export || 'ultrafast')),
  video: masuk.video && typeof masuk.video === 'object' ? masuk.video : { width: 1920, height: 1080, rateNum: 30, rateDen: 1 }
};
rencana.call = { tool: 'project_create', arguments: { location: rencana.location, name: rencana.name, video: rencana.video } };
return [rencana];

const rencana = { ...(($node['Susun Rencana'] || [{}])[0] || {}) };
if (!$json.ok) throw new Error('project_create gagal: ' + (($json.body && $json.body.error) || $json.error || JSON.stringify($json.data || $json.content || $json)));
const proyek = ($json.data && $json.data.project) || {};
if (proyek.path) rencana.project_path = proyek.path;
rencana.call = { tool: 'media_import', arguments: { path: rencana.project_path, file: rencana.media } };
return [rencana];

const rencana = { ...(($node['Setelah Buat Proyek'] || [{}])[0] || {}) };
if (!$json.ok) throw new Error('media_import gagal: ' + (($json.body && $json.body.error) || $json.error || JSON.stringify($json.data || $json.content || $json)));
const data = $json.data || {};
const mediaId = (data.media && data.media.id) || data.mediaId || data.id;
if (!mediaId) throw new Error('media_import tidak mengembalikan id media: ' + JSON.stringify(data));
rencana.media_id = mediaId;
rencana.call = { tool: 'clips_add_sequence', arguments: { path: rencana.project_path, mediaIds: [mediaId], start: 0 } };
return [rencana];

const rencana = { ...(($node['Setelah Impor'] || [{}])[0] || {}) };
if (!$json.ok) throw new Error('clips_add_sequence gagal: ' + (($json.body && $json.body.error) || $json.error || JSON.stringify($json.data || $json.content || $json)));
rencana.call = { tool: 'title_add', arguments: { path: rencana.project_path, start: 0, duration: 3, above: true, style: { content: rencana.title } } };
return [rencana];

const rencana = { ...(($node['Setelah Susun Klip'] || [{}])[0] || {}) };
if (!$json.ok) throw new Error('title_add gagal: ' + (($json.body && $json.body.error) || $json.error || JSON.stringify($json.data || $json.content || $json)));
rencana.call = { tool: 'project_save', arguments: { path: rencana.project_path } };
return [rencana];

const rencana = { ...(($node['Setelah Judul'] || [{}])[0] || {}) };
if (!$json.ok) throw new Error('project_save gagal: ' + (($json.body && $json.body.error) || $json.error || JSON.stringify($json.data || $json.content || $json)));
rencana.call = { tool: 'export_start', arguments: { path: rencana.project_path, output: rencana.output, preset: rencana.preset } };
return [rencana];

const rencana = { ...(($node['Setelah Simpan'] || [{}])[0] || {}) };
if (!$json.ok) throw new Error('export_start gagal: ' + (($json.body && $json.body.error) || $json.error || JSON.stringify($json.data || $json.content || $json)));
const job = ($json.data && $json.data.job) || null;
if (!job) throw new Error('export_start tidak mengembalikan job id: ' + JSON.stringify($json.data || {}));
rencana.export_job = job;
rencana.call = { tool: 'export_wait', arguments: { job, timeoutSeconds: 1800 }, timeoutMs: 1860000 };
return [rencana];

const rencana = ($node['Setelah Mulai Export'] || [{}])[0] || {};
if (!$json.ok) throw new Error('export_wait gagal: ' + (($json.body && $json.body.error) || $json.error || JSON.stringify($json.data || $json.content || $json)));
const state = ($json.data && $json.data.state) || 'unknown';
return [{
  ok: state === 'done',
  state,
  project: rencana.project_path,
  output_file: rencana.output,
  export_job: rencana.export_job,
  siap_upload_youtube: state === 'done',
  catatan: 'File hasil export siap direview. Upload ke YouTube dilakukan supervisor lewat KRA > Creator Integration Settings (UPLOAD TO YOUTUBE STUDIO); workflow ini tidak mengupload apa pun.'
}];
